import type { PluginModule } from "../app/PluginHost";

/** 单条业务路由声明：view 名对应 View catalog 键；group/restore 逐字来自该 View 的 sidecar。 */
export interface GeneratedPluginRoute {
    readonly id: string;
    readonly view: string;
    readonly group: string;
    readonly restore: "keep-mounted" | "reopen" | "fallback" | "discard";
}

/** 入口启动目标（LaunchPort.launch 的载荷；§7.4 点击唯一出口）：进入玩法，或打开一个 plugin route。 */
export type GeneratedLaunchTarget =
    | {
        readonly kind: "gameplay";
        readonly gameplayId: string;
        /** 带参 launch（MF9-B4）：原样交给该玩法 GameplayModule.validateLaunch 做 exact 校验。 */
        readonly payload?: Readonly<Record<string, unknown>>;
        /** 一个玩法多房型入口：覆盖 joiner 的缺省 profile（codegen 已校验 ∈ manifest.profiles）。 */
        readonly profile?: string;
    }
    | { readonly kind: "route"; readonly routeId: string };

/** 菜单入口贡献（§7.4：菜单唯一数据源）；只有身份与元数据，⛔ 无位置字段（位置见 GENERATED_HOST）。 */
export interface GeneratedMenuContribution {
    readonly entryId: string;
    readonly pluginId: string;
    readonly label: string;
    readonly labelKey: string;
    readonly icon?: string;
    readonly launch: GeneratedLaunchTarget;
}

export interface GeneratedPluginDescriptor {
    readonly id: string;
    readonly resident: boolean;
    readonly dependencies: readonly string[];
    readonly routes: readonly GeneratedPluginRoute[];
    readonly menu: readonly GeneratedMenuContribution[];
    /** plugin module 加载器（静态字面量动态 import，Non-intrusive §5.3）；无 = 静态常驻。 */
    readonly load?: () => Promise<PluginModule>;
}

